$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
. (Join-Path $PSScriptRoot '../capture-character-authored.ps1')
function RejectCharacter([scriptblock]$Action){$Caught=$false;try{& $Action}catch{$Caught=$true};if(-not $Caught){throw 'Invalid sequential character input accepted.'}}
$Methods=@{momo='Momo';lulu='Lulu';pom='Pom';fio='Fio';miel='Miel'}
foreach($Id in @(Get-CharacterAuthoredIds)){
    $ArgsList=@(Get-CharacterAuthoredArguments 'repo with spaces' 'run with spaces' $Id ('a'*40) ('b'*64))
    $Expected='Mofumachi.Tests.ExperienceCaptureTests.'+$Methods[$Id]+'AuthoredPartsPreserveIdentityInputAndState'
    if($ArgsList[[Array]::IndexOf($ArgsList,'-testFilter')+1] -ne $Expected -or '-mofumachiCharacterPreview' -notin $ArgsList -or '-quit' -in $ArgsList){throw 'Wrong single-character route.'}
}
foreach($Id in @('noah','../momo','', 'MOMO')+@($Methods.Keys | Where-Object {$_ -notin @(Get-CharacterAuthoredIds)})){
    RejectCharacter {Get-CharacterAuthoredArguments 'repo' 'out' $Id ('a'*40) ('b'*64)}
}
$Root=Join-Path ([IO.Path]::GetTempPath()) ('mofu-character-route-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $Root | Out-Null
try{
    $Folder=Join-Path $Root 'Assets/Mofumachi/Resources/Mofumachi/CharacterAuthored';New-Item -ItemType Directory -Path $Folder -Force | Out-Null
    [IO.File]::WriteAllText((Join-Path $Folder '.owner'),'other run');RejectCharacter {Remove-OwnedCharacterResources $Root $Root};if(-not(Test-Path -LiteralPath $Folder)){throw 'Foreign resources deleted.'}
    [IO.File]::WriteAllText((Join-Path $Folder '.owner'),$Root);Remove-OwnedCharacterResources $Root $Root;if(Test-Path -LiteralPath $Folder){throw 'Owned resources not cleaned.'}
    $File=Join-Path $Root 'Assets/Mofumachi/Core/link.xml';New-Item -ItemType Directory -Path (Split-Path -Parent $File) -Force | Out-Null;[IO.File]::WriteAllText($File,"<linker>`n</linker>`n")
    $Digest=(Get-FileHash -LiteralPath $File -Algorithm SHA256).Hash.ToLowerInvariant()
    $Record=Join-Path $Root 'References/VisualLock/noah-authored-approved-2026-10-30.json';New-Item -ItemType Directory -Path (Split-Path -Parent $Record) -Force | Out-Null
    @{user_approved=$true;frozen_files=@(@{path='Assets/Mofumachi/Core/link.xml';sha256=$Digest;text_normalized=$true})} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $Record -Encoding UTF8
    [IO.File]::WriteAllText($File,"<linker>`r`n</linker>`r`n");Assert-NoahAuthoredMasterFixed $Root
    [IO.File]::AppendAllText($File,'changed');RejectCharacter {Assert-NoahAuthoredMasterFixed $Root}
    $Resource=Join-Path $Root 'Assets/Mofumachi/Resources/Mofumachi/CharacterAuthored/momo';New-Item -ItemType Directory -Path $Resource -Force | Out-Null
    $Before=Get-CharacterAuthoredSourceFingerprint $Root
    [IO.File]::WriteAllText((Join-Path $Resource 'atlas.png'),'synthetic generated bytes, not a PNG')
    if((Get-CharacterAuthoredSourceFingerprint $Root) -ne $Before){throw 'Temporary resource changed source identity.'}
    [IO.File]::AppendAllText($File,'source change');if((Get-CharacterAuthoredSourceFingerprint $Root) -eq $Before){throw 'Real input change escaped source identity.'}
    $Output=Join-Path $Root 'screenshots/momo-authored';New-Item -ItemType Directory -Path $Output -Force | Out-Null
    $ImagePath=Join-Path $Output 'synthetic.png';[IO.File]::WriteAllText($ImagePath,'synthetic validator bytes, not native evidence')
    $Image=@{file='synthetic.png';sha256=(Get-FileHash -LiteralPath $ImagePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $ImagePath).Length;width=720;height=1280}
    $Pair=@{changed_pixels=20;outside_allowed_pixels=0;before=$Image;after=$Image}
    foreach($Flag in @('frame_unchanged','actors_unchanged','other_five_unchanged','camera_unchanged','water_clock_unchanged','water_phase_unchanged','state_unchanged','store_writes_unchanged','world_model_unchanged')){$Pair[$Flag]=$true}
    $Proof=@{character='momo';gitRevision=('a'*40);productFingerprint=('b'*64);input_sha256=('c'*64);native_unity=$true;tap_verified=$true;conversation_verified=$true;save_unchanged=$true;greeting_authored=$true;talk_authored=$true;blink_authored=$true;blink_image=$Image;adopted=$false;pixel_verified=$false;sorting_examples=5;sorting_images=@($Image)*5;frames=@($Image)*8;pairs=@($Pair)*6;observed_directions=@('Front','Left','Right','Back')}
    '<test-run><test-case fullname="Mofumachi.Tests.ExperienceCaptureTests.MomoAuthoredPartsPreserveIdentityInputAndState" result="Passed" /></test-run>' | Set-Content -LiteralPath (Join-Path $Root 'playmode.xml') -Encoding UTF8
    @{characterId='momo';input_sha256=('c'*64)} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $Root 'prepared.json') -Encoding UTF8
    $ProofPath=Join-Path $Output 'proof.json';$Good=$Proof | ConvertTo-Json -Depth 8;Set-Content -LiteralPath $ProofPath -Value $Good -Encoding UTF8
    Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)
    foreach($Flag in @('tap_verified','conversation_verified','save_unchanged','greeting_authored','talk_authored','blink_authored','native_unity','adopted','pixel_verified')){
        $Bad=$Good | ConvertFrom-Json;$Bad.$Flag=-not $Bad.$Flag;$Bad | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $ProofPath -Encoding UTF8
        RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)}
    }
    $Bad=$Good | ConvertFrom-Json;$Bad.observed_directions=@('Front','Left','Right');$Bad | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $ProofPath -Encoding UTF8;RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)}
    $Bad=$Good | ConvertFrom-Json;$Bad.pairs[0].outside_allowed_pixels=1;$Bad | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $ProofPath -Encoding UTF8;RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)}
    $Bad=$Good | ConvertFrom-Json;$Bad.pairs[0].other_five_unchanged=$false;$Bad | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $ProofPath -Encoding UTF8;RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)}
    Set-Content -LiteralPath $ProofPath -Value $Good -Encoding UTF8
    foreach($Id in @(Get-CharacterAuthoredIds | Where-Object {$_ -ne 'momo'})){
        $OtherOutput=Join-Path $Root ('screenshots/'+$Id+'-authored');New-Item -ItemType Directory -Path $OtherOutput -Force | Out-Null
        Copy-Item -LiteralPath $ImagePath -Destination (Join-Path $OtherOutput 'synthetic.png')
        $OtherProof=$Good | ConvertFrom-Json;$OtherProof.character=$Id
        $OtherProof | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $OtherOutput 'proof.json') -Encoding UTF8
        ('<test-run><test-case fullname="Mofumachi.Tests.ExperienceCaptureTests.'+$Methods[$Id]+'AuthoredPartsPreserveIdentityInputAndState" result="Passed" /></test-run>') | Set-Content -LiteralPath (Join-Path $Root 'playmode.xml') -Encoding UTF8
        @{characterId=$Id;input_sha256=('c'*64)} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $Root 'prepared.json') -Encoding UTF8
        Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64) $Id
        RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64) 'momo'}
        $OtherProof.character='momo';$OtherProof | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $OtherOutput 'proof.json') -Encoding UTF8
        RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64) $Id}
    }
    '<test-run><test-case fullname="Mofumachi.Tests.ExperienceCaptureTests.MomoAuthoredPartsPreserveIdentityInputAndState" result="Passed" /></test-run>' | Set-Content -LiteralPath (Join-Path $Root 'playmode.xml') -Encoding UTF8
    @{characterId='momo';input_sha256=('c'*64)} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $Root 'prepared.json') -Encoding UTF8
    [IO.File]::AppendAllText($ImagePath,'tampered');RejectCharacter {Assert-CharacterAuthoredProof $Root ('a'*40) ('b'*64)}
    Write-Host 'Single-character guards passed: prepared character methods and mismatched proof rejection, future/Noah characters rejected, owned cleanup, CRLF master protection, source identity. No Unity/APK/device.'
}finally{Remove-Item -LiteralPath $Root -Recurse -Force}
